// --- atf_unit.FDb.unittest.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool atf_unit::unittest_XrefMaybe(atf_unit::FUnittest &row) {
    bool retval = true;
    (void)row;
    // insert unittest into index ind_unittest
    if (true) { // user-defined insert condition
        bool success = ind_unittest_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "atf_unit.duplicate_key  xref:atf_unit.FDb.ind_unittest"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

// --- atf_unit.FDb._db.ReadArgv
// Read argc,argv into the fields of atf_unit.FDb.cmdline (and any base command line)
// via atf_unit_ReadArgv; then apply -help/-version and load floadtuples input.
void atf_unit::ReadArgv() {
    command::atf_unit &cmd = atf_unit::_db.cmdline;
    algo::cstring err;
    algo::StringAry args;
    for (int argidx=1; argidx < algo_lib::_db.argc; argidx++) {// skip process name
        ary_Alloc(args) = algo_lib::_db.argv[argidx];
    }
    command::atf_unit_ReadArgv(cmd, args, err);
    bool dohelp = false;
    bool doexit=false;
    if (algo_lib::_db.cmdline.help) {
        dohelp = true;
        doexit = true;
        algo_lib::_db.exit_code = 1; // help exits with non-zero status code
    } else if (algo_lib::_db.cmdline.version) {
        // -ver output goes to stdout
        prlog(algo::gitinfo_Get());
        doexit = true;
    } else if (algo_lib::_db.cmdline.signature) {
        ind_beg(algo_lib::_db_dispsigcheck_curs,dispsigcheck,algo_lib::_db) {
            // dispsig goes to stdout
            dmmeta::Dispsigcheck out;
            dispsigcheck_CopyOut(dispsigcheck,out);
            prlog(out);
        }ind_end
        doexit = true;
    }
    algo_lib_logcat_debug.enabled = algo_lib::_db.cmdline.debug;
    algo_lib_logcat_verbose.enabled = algo_lib::_db.cmdline.verbose > 0;
    algo_lib_logcat_verbose2.enabled = algo_lib::_db.cmdline.verbose > 1;
    // dmmeta.floadtuples:command.atf_unit.data_dir
    if (!dohelp && err=="") {
        algo_lib::ResetErrtext();
        if (!atf_unit::LoadTuplesMaybe(cmd.data_dir,true)) {
            err << "atf_unit.load_input  "<<algo_lib::DetachBadTags()<<eol;
        }
    }
    if (err != "") {
        algo_lib::_db.exit_code=1;
        prerr_(err); // already has eol
        doexit=true;
    }
    if (dohelp) {
        prlog(command::atf_unit_help);
    }
    if (doexit) {
        _exit(algo_lib::_db.exit_code);
    }
    algo_lib::ResetErrtext();
}

// --- atf_unit.FDb._db.MainLoop
// Main loop.
void atf_unit::MainLoop() {
    algo::SchedTime time(algo::get_cycles());
    algo_lib::_db.clock          = time;
    do {
        algo_lib::_db.next_loop.value = algo_lib::_db.limit;
        atf_unit::Steps();
    } while (algo_lib::_db.next_loop < algo_lib::_db.limit);
}

// --- atf_unit.FDb._db.Step
// Main step
void atf_unit::Step() {
}

// --- atf_unit.FDb._db.InitReflection
// Load statically available data into tables, register tables and database.
static void atf_unit::InitReflection() {
    algo_lib::FImdb &row = algo_lib::imdb_Alloc();
    row.imdb               = "atf_unit";
    row.InsertStrptrMaybe  = NULL;
    row.RemoveStrptrMaybe  = NULL;
    row.Step               = NULL;
    row.MainLoop           = atf_unit::MainLoop;
    algo_lib::imdb_XrefMaybe(row);

    algo::Imtable t_trace;
    t_trace.imtable         = "atf_unit.trace";
    t_trace.ssimfile        = "";
    t_trace.size            = sizeof(atf_unit::trace);
    t_trace.comment.value   = "";
    t_trace.c_RowidFind     = trace_RowidFind;
    t_trace.NItems          = trace_N;
    t_trace.Print           = (algo::ImrowPrintFcn)atf_unit::trace_Print;
    algo_lib::imtable_InsertMaybe(t_trace);


    // -- load signatures of existing dispatches --
}

