// --- atf_unit.TypeB..ReadFieldMaybe
bool atf_unit::TypeB_ReadFieldMaybe(atf_unit::TypeB& parent, algo::strptr field, algo::strptr strval) {
    bool retval = true;
    atf_unit::FieldId field_id;
    (void)value_SetStrptrMaybe(field_id,field);
    switch(field_id) {
        case atf_unit_FieldId_typea: {
            retval = i32_ReadStrptrMaybe(parent.typea, strval);
        } break;
        case atf_unit_FieldId_j: {
            retval = i32_ReadStrptrMaybe(parent.j, strval);
        } break;
        default: {
            retval = false;
            algo_lib::AppendErrtext("comment", "unrecognized attr");
        } break;
    }
    if (!retval) {
        algo_lib::AppendErrtext("attr",field);
    }
    return retval;
}

// --- atf_unit.TypeB..ReadStrptrMaybe
// Read fields of atf_unit::TypeB from an ascii string.
// The format of the string is an ssim Tuple
bool atf_unit::TypeB_ReadStrptrMaybe(atf_unit::TypeB &parent, algo::strptr in_str) {
    bool retval = true;
    retval = algo::StripTypeTag(in_str, "atf_unit.TypeB");
    ind_beg(algo::Attr_curs, attr, in_str) {
        retval = retval && TypeB_ReadFieldMaybe(parent, attr.name, attr.value);
    }ind_end;
    return retval;
}

// --- atf_unit.TypeB..FmtJson
// Create JSON representation of atf_unit::TypeB under PARENT node
// cfmt:atf_unit.TypeB.Json  printfmt:Auto
lib_json::FNode * atf_unit::TypeB_FmtJson(atf_unit::TypeB row, lib_json::FNode *parent) {
    lib_json::FNode *objnode = &lib_json::node_Alloc();
    objnode->p_parent = parent?parent:objnode;
    objnode->type   = lib_json_FNode_type_object;
    node_XrefMaybe(*objnode);

    lib_json::FNode *typea_node = &lib_json::node_Alloc();
    typea_node->p_parent = objnode;
    typea_node->type   = lib_json_FNode_type_field;
    typea_node->value  = "typea";
    node_XrefMaybe(*typea_node);
    i32_FmtJson(row.typea,typea_node);

    lib_json::FNode *j_node = &lib_json::node_Alloc();
    j_node->p_parent = objnode;
    j_node->type   = lib_json_FNode_type_field;
    j_node->value  = "j";
    node_XrefMaybe(*j_node);
    i32_FmtJson(row.j,j_node);
    return objnode;
}

