// --- atf_unit...SizeCheck
inline static void atf_unit::SizeCheck() {
}

// --- atf_unit...StaticCheck
void atf_unit::StaticCheck() {
    algo_assert(sizeof(atf_unit::unittest_step_hook) == 8); // csize:atf_unit.unittest_step_hook
    algo_assert(_offset_of(atf_unit::FMsg_curs, msglen) + sizeof(((atf_unit::FMsg_curs*)0)->msglen) == sizeof(atf_unit::FMsg_curs));
    algo_assert(_offset_of(atf_unit::FieldId, value) + sizeof(((atf_unit::FieldId*)0)->value) == sizeof(atf_unit::FieldId));
}

// --- atf_unit...main
int main(int argc, char **argv) {
    try {
        algo_lib::FDb_Init();
        lib_ams::FDb_Init();
        lib_curl::FDb_Init();
        lib_exec::FDb_Init();
        lib_json::FDb_Init();
        lib_netio::FDb_Init();
        lib_sql::FDb_Init();
        lib_ws::FDb_Init();
        atf_unit::FDb_Init();
        algo_lib::_db.argc = argc;
        algo_lib::_db.argv = argv;
        algo_lib::IohookInit();
        algo_lib::_db.clock = algo::CurrSchedTime(); // initialize clock
        atf_unit::ReadArgv(); // dmmeta.main:atf_unit
        atf_unit::Main(); // user-defined main
    } catch(algo_lib::ErrorX &x) {
        prerr("atf_unit.error  " << x); // there may be additional hints in DetachBadTags
        algo_lib::_db.exit_code = 1;
    }
    if (algo_lib::_db.last_signal) {
        algo_lib::_db.exit_code = 1;
    }
    try {
        atf_unit::FDb_Uninit();
        lib_ws::FDb_Uninit();
        lib_sql::FDb_Uninit();
        lib_netio::FDb_Uninit();
        lib_json::FDb_Uninit();
        lib_exec::FDb_Uninit();
        lib_curl::FDb_Uninit();
        lib_ams::FDb_Uninit();
        algo_lib::FDb_Uninit();
    } catch(algo_lib::ErrorX &) {
        // don't print anything, might crash
        algo_lib::_db.exit_code = 1;
    }
    // only the lower 1 byte makes it to the outside world
    (void)i32_UpdateMin(algo_lib::_db.exit_code,255);
    return algo_lib::_db.exit_code;
}

